INSERT INTO processes (id, name, description, launch_params_schema, read_resources, write_resources, dependencies, duplicate_policy, default_priority, timeout_sec, max_parallelism, snapshot_read, created_at) VALUES ('BP-01', 'Проверка заявки на кредит', 'Оценка клиента, кредитной истории, текущих задолженностей и платёжеспособности по заявке', '{"required": ["application_number"], "optional": ["as_of_date"]}'::jsonb, ARRAY['clients_db', 'credit_registry']::text[], ARRAY['risk_results_store']::text[], '[{"process_id": "BP-02", "mode": "FRESH_CLIENT_DATA"}]'::jsonb, 'ALLOW_VERSIONED', 1, 120, 8, TRUE, '2026-11-25T12:00:00+00:00') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, read_resources = EXCLUDED.read_resources, write_resources = EXCLUDED.write_resources, dependencies = EXCLUDED.dependencies, default_priority = EXCLUDED.default_priority, duplicate_policy = EXCLUDED.duplicate_policy;
INSERT INTO processes (id, name, description, launch_params_schema, read_resources, write_resources, dependencies, duplicate_policy, default_priority, timeout_sec, max_parallelism, snapshot_read, created_at) VALUES ('BP-02', 'Обновление информации о клиентах', 'Получение данных из внешних источников, валидация, обновление клиентской базы и версии', '{"required": ["update_date"], "optional": ["client_ids"]}'::jsonb, ARRAY['clients_db']::text[], ARRAY['clients_db']::text[], '[]'::jsonb, 'QUEUE', 3, 300, 2, FALSE, '2026-11-25T12:00:00+00:00') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, read_resources = EXCLUDED.read_resources, write_resources = EXCLUDED.write_resources, dependencies = EXCLUDED.dependencies, default_priority = EXCLUDED.default_priority, duplicate_policy = EXCLUDED.duplicate_policy;
INSERT INTO processes (id, name, description, launch_params_schema, read_resources, write_resources, dependencies, duplicate_policy, default_priority, timeout_sec, max_parallelism, snapshot_read, created_at) VALUES ('BP-03', 'Мониторинг просроченных платежей', 'Сравнение графиков и фактических платежей за дату мониторинга, расчёт просрочек', '{"required": ["monitoring_date"]}'::jsonb, ARRAY['credit_registry', 'payment_schedules', 'payments_system']::text[], ARRAY['risk_results_store']::text[], '[{"process_id": "PAYMENTS_SYNC", "mode": "ACTUAL_PAYMENTS"}]'::jsonb, 'REJECT', 2, 600, 4, TRUE, '2026-11-25T12:00:00+00:00') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, read_resources = EXCLUDED.read_resources, write_resources = EXCLUDED.write_resources, dependencies = EXCLUDED.dependencies, default_priority = EXCLUDED.default_priority, duplicate_policy = EXCLUDED.duplicate_policy;
INSERT INTO processes (id, name, description, launch_params_schema, read_resources, write_resources, dependencies, duplicate_policy, default_priority, timeout_sec, max_parallelism, snapshot_read, created_at) VALUES ('BP-04', 'Формирование отчёта о кредитном портфеле', 'Агрегация задолженности, доли просрочек и группировка по регионам и типам клиентов', '{"required": ["report_date"]}'::jsonb, ARRAY['credit_registry', 'risk_results_store', 'clients_db']::text[], ARRAY['portfolio_reports_store']::text[], '[{"process_id": "BP-03", "same_date": true, "required_status": "COMPLETED"}]'::jsonb, 'QUEUE', 4, 900, 2, TRUE, '2026-11-25T12:00:00+00:00') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, read_resources = EXCLUDED.read_resources, write_resources = EXCLUDED.write_resources, dependencies = EXCLUDED.dependencies, default_priority = EXCLUDED.default_priority, duplicate_policy = EXCLUDED.duplicate_policy;
INSERT INTO processes (id, name, description, launch_params_schema, read_resources, write_resources, dependencies, duplicate_policy, default_priority, timeout_sec, max_parallelism, snapshot_read, created_at) VALUES ('PAYMENTS_SYNC', 'Внешнее обновление информации о платежах', 'Внешний процесс загрузки фактических платежей в платёжную систему (пересекается с BP-03)', '{"required": ["sync_date"]}'::jsonb, '{}'::text[], ARRAY['payments_system']::text[], '[]'::jsonb, 'QUEUE', 2, 300, 1, FALSE, '2026-11-25T12:00:00+00:00') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, read_resources = EXCLUDED.read_resources, write_resources = EXCLUDED.write_resources, dependencies = EXCLUDED.dependencies, default_priority = EXCLUDED.default_priority, duplicate_policy = EXCLUDED.duplicate_policy;
